select t.* from(SELECT ROW_NUMBER() over() as ROWNUM, CDATE purNetValueDate,/*净值日*/ TDY_UNIT_VALUE purUnitNetValue,/*净值*/ TDY_SHARE_AMT purDealNum,/*剩余份额*/ TDY_UNPAID_INTINCEXP purDealAmt/*剩余可分配利息*/ FROM BOK_POSITION_PRD WHERE FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND CDATE < to_date(#{netValueDate,jdbcType=VARCHAR}, 'yyyy-mm-dd') and not exists ( SELECT 1 FROM BOK_POSITION_PRD p WHERE p.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND p.CDATE < to_date(#{netValueDate,jdbcType=VARCHAR}, 'yyyy-mm-dd') AND p.CDATE > BOK_POSITION_PRD.CDATE )
AND CDATE = (SELECT max(CDATE) FROM BOK_POSITION_PRD WHERE CDATE <= to_date(decode(#{dealDate,jdbcType=VARCHAR},'',null,#{dealDate,jdbcType=VARCHAR}), 'yyyy-mm-dd') AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR})
) t where t.ROWNUM = 1

		SELECT
    		TERM_MAX id,TERM_MAX text
		FROM PRD_LAYER_PARAM WHERE P_FINPROD_ID = #{finprodId}
